{"path": "/tmp/sv-acf971f3617b4fa794cf48c608e387d3/install-sdk.ps1", "file_text": "<#
.SYNOPSIS
    Installs the .NET SDK version specified in global.json using the official dotnet-install script.
.PARAMETER InstallDir
    Directory to install the SDK into. Defaults to .dotnet/ in the repository root.
#>
[CmdletBinding()]
param(
    [string]$InstallDir
)

$ErrorActionPreference = 'Stop'

$RepoRoot = Split-Path -Parent $PSCommandPath
$GlobalJson = Join-Path $RepoRoot 'global.json'

if (-not (Test-Path $GlobalJson)) {
    Write-Error "global.json not found at $GlobalJson"
    exit 1
}

$json = Get-Content $GlobalJson -Raw | ConvertFrom-Json
$sdkVersion = $json.sdk.version

if (-not $sdkVersion) {
    Write-Error "Could not parse SDK version from global.json"
    exit 1
}

if (-not $InstallDir) {
    $InstallDir = Join-Path $RepoRoot '.dotnet'
}

Write-Host "Installing .NET SDK $sdkVersion to $InstallDir ..."

$installScript = Join-Path ([System.IO.Path]::GetTempPath()) 'dotnet-install.ps1'

try {
    Invoke-WebRequest -Uri 'https://dot.net/v1/dotnet-install.ps1' -OutFile $installScript -UseBasicParsing

    & $installScript -Version $sdkVersion -InstallDir $InstallDir
}
finally {
    if (Test-Path $installScript) {
        Remove-Item $installScript -Force
    }
}

Write-Host ""
Write-Host "Done. SDK installed to: $InstallDir"
Write-Host ""
Write-Host "Set environment variables before building:"
Write-Host "  `$env:DOTNET_ROOT = '$InstallDir'"
Write-Host "  `$env:PATH = '$InstallDir;' + `$env:PATH"
"}
